+        __ imulq(rax, rax, term);
+      }
+      if ((j + i) >= limbs) {
+        __ imulq(d, d, term);
+      }
+      __ addq(c[(i + j) % limbs], d);
+      __ addq(c[(i + j + 1) % limbs], rax);
+    }
