+  __ mov64(mask, CARRY_ADD);
+  __ movq(carry, mask);
+  __ addq(carry, c[3]);
+  __ sarq(carry, bpl);
+  __ addq(c[4], carry);
+  __ shlq(carry, bpl);
+  __ subq(c[3], carry);
+
+  // Limb 4
+  __ movq(carry, mask);
+  __ addq(carry, c[4]);
+  __ sarq(carry, bpl);
+
+  // Reduce high order limb and fold back into low order limb
+  __ mov64(rax, term);
+  __ imulq(carry);
+  __ addq(c[0], rax);
+
+  __ shlq(carry, bpl);
+  __ subq(c[4], carry);
+
