+    target->add("-*credential *");
+    target->add("-*jaas*config *");
+    target->add("-*passphrase *");
+    target->add("-*passwd *");
+    target->add("-*password *");
+    target->add("-*private*key *");
+    target->add("-*pwd *");
+    target->add("-*secret *");
+    target->add("-*token *");
