+                      cx + ck, cy + r,
+                      cx,      cy + r);
+    hb_draw_cubic_to (dfuncs, draw_data, st,
+                      cx - ck, cy + r,
+                      cx - r,  cy + ck,
+                      cx - r,  cy);
+    hb_draw_cubic_to (dfuncs, draw_data, st,
+                      cx - r,  cy - ck,
+                      cx - ck, cy - r,
+                      cx,      cy - r);
+    hb_draw_cubic_to (dfuncs, draw_data, st,
+                      cx + ck, cy - r,
+                      cx + r,  cy - ck,
+                      cx + r,  cy);
+  }
+  else
+  {
+    hb_draw_cubic_to (dfuncs, draw_data, st,
+                      cx + r, cy - ck,
+                      cx + ck, cy - r,
+                      cx,      cy - r);
+    hb_draw_cubic_to (dfuncs, draw_data, st,
+                      cx - ck, cy - r,
+                      cx - r,  cy - ck,
+                      cx - r,  cy);
+    hb_draw_cubic_to (dfuncs, draw_data, st,
+                      cx - r,  cy + ck,
+                      cx - ck, cy + r,
+                      cx,      cy + r);
+    hb_draw_cubic_to (dfuncs, draw_data, st,
+                      cx + ck, cy + r,
+                      cx + r,  cy + ck,
+                      cx + r,  cy);
+  }
