+    colors = (hb_color_t *) hb_malloc (sizeof (hb_color_t) * n_stops);
+    if (!angles || !colors)
+    {
+      hb_free (angles);
+      hb_free (colors);
+      return;
+    }
+    dynamic = true;
+  }
