+          hb_color_t c = hb_color_lerp (col0, col1, f);
+          emit_patch (a0_l, col0, HB_2_PI, c, user_data);
+          goto done;
+        }
+        else
+          emit_patch (a0_l, col0, a1_l, col1, user_data);
+      }
+    }
+  }
+
+done:
+  if (dynamic)
+  {
+    hb_free (angles);
+    hb_free (colors);
+  }
+}
