+        offset = checkFromIndexSize(offset, species.vectorByteSize(), ms.byteSize());
+        Float16Species vsp = (Float16Species) species;
+        return vsp.dummyVector().fromMemorySegment0(ms, offset).maybeSwap(bo);
+    }
