+    @ForceInline
+    private void conditionalStoreNYI(int offset,
+                                     Float16Species vsp,
+                                     VectorMask<Float16> m,
+                                     int scale,
+                                     int limit) {
+        if (offset < 0 || offset + vsp.laneCount() * scale > limit) {
+            String msg =
+                String.format("unimplemented: store @%d in [0..%d), %s in %s",
+                              offset, limit, m, vsp);
+            throw new AssertionError(msg);
+        }
+    }
