+        /*package-private*/
+        @Override
+        @ForceInline
+        final Float16Vector broadcastBits(long bits) {
+            return (Float16Vector)
+                VectorSupport.fromBitsCoerced(
+                    vectorType, laneTypeOrdinal(), laneCount,
