+        int i = init;
+        while (i < 0) {
+            // while implies: init in [min_int .. 0]
+            // That contradicts the "if" above: empty intersection
+            //
+            // See CountedLoopConverter::filtered_type_from_dominators:
+            //   rtn_t = rtn_t->join(if_t)->is_int()
+            // -> top type in join, fails "is_int".
+            i = (short)(i + 1);
+        }
+        return 0;
+    }
