+    interface ToFloat16F {
+        short apply(int i);
+    }
+
+    static short[] fill(int s , ToFloat16F f) {
+        return fill(new short[s], f);
+    }
+
+    static short[] fill(short[] a, ToFloat16F f) {
+        for (int i = 0; i < a.length; i++) {
+            a[i] = f.apply(i);
+        }
+        return a;
+    }
