+                            SSLEngineResult.HandshakeStatus.NEED_WRAP) {
+                        buf.compact();
+                        again = false;
+                        continue;
+                    }
+                    exit = true;
+                }
+
+                doTask(r, engine);
+
+                buf.clear();
+                getWriteBuf().flip();
+                sc = false;
+
+                while (!sc) {
+                    Thread.sleep(delay);
+                }
+
+                while (true) {
+                    inData.clear();
+                    r = engine.unwrap(getReadBuf(), inData);
+                    log("read unwrap", r);
+
+                    if (DEBUG && r.getStatus() != SSLEngineResult.Status.OK) {
+                        dumpBuffers("inData", inData);
+                        dumpBuffers("readBuf", getReadBuf());
