+                inData.clear();
+                getReadBuf().compact();
+
+                totalDataLen += r.bytesProduced();
+                sc = false;
+
+                if (!firstNotHandshake &&
+                    r.getHandshakeStatus() ==
+                        SSLEngineResult.HandshakeStatus.NOT_HANDSHAKING) {
