+            if (cipherSuite != null && !cipherSuite.isEmpty()) {
+                engine.setEnabledCipherSuites(new String[] { cipherSuite });
+            }
+        }
+
+        @Override
+        public void run() {
+            try {
+                if (serverWrites) {
+                    writeLoop();
+                } else {
+                    readLoop();
+                }
+            } catch (Exception e) {
+                System.out.println("server: " + e.getMessage());
+                e.printStackTrace();
+            }
+            System.out.println("Server closed");
+        }
+
+        @Override
+        ByteBuffer getWriteBuf() {
+            return sToc;
+        }
+
+        @Override
+        ByteBuffer getReadBuf() {
+            return cTos;
+        }
+    }
+
+    static class Client extends KeyUpdateOnce implements Runnable {
+        Client() throws Exception {
+            super();
+            engine = initContext().createSSLEngine();
+            engine.setUseClientMode(true);
+        }
+
+        @Override
+        public void run() {
+            try {
+                if (!serverWrites) {
+                    writeLoop();
+                } else {
+                    readLoop();
+                }
+            } catch (Exception e) {
+                System.out.println("client: " + e.getMessage());
+                e.printStackTrace();
+            }
+            System.out.println("Client closed");
+        }
+
+        @Override
+        ByteBuffer getWriteBuf() {
+            return cTos;
+        }
+
+        @Override
+        ByteBuffer getReadBuf() {
+            return sToc;
+        }
+    }
+}

