+                    private Lib lib;
+                }
+                """);
+
+        boolean[] state = new boolean[] {false, false};
+        try (FM fm = new FM(compiler.getStandardFileManager(null, null, null), state)) {
+            com.sun.source.util.JavacTask task = (com.sun.source.util.JavacTask) compiler.getTask(
