+        Path jar = createJar();
+
+        JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
+        JavaFileObject compilationUnit = SimpleJavaFileObject.forSource(URI.create("string:///Test.java"),
+                """
+                public class Test {
+                    private Lib lib;
+                }
+                """);
+
+        boolean[] state = new boolean[] {false, false};
