+                .options("-d", classes.toString(), "-AskipGetElement=true")
+                .sources("""
+                         record Repro(String name) {
+                             Repro {
+                                 name = name.trim();
+                             }
+                         }
+                         """)
+                .processors(new ProcessorImpl())
