+        Files.createDirectories(classes);
+        new JavacTask(tb)
+                .options("-d", classes.toString())
+                .sources("""
+                         record Repro(String name) {
+                             Repro(String name) {
+                                 this.name = name.trim();
+                             }
+                         }
+                         """)
